import pandas as pd
import sys

# Test 1: Series with 2**64 (out-of-range)
try:
    result = pd.Series([2**64], dtype=object).convert_dtypes()
    probe('series_2_64_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_2_64_error', 1)

# Test 2: Series with -(2**63)-1 (out-of-range)
try:
    result = pd.Series([-(2**63)-1], dtype=object).convert_dtypes()
    probe('series_neg_2_63_1_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_neg_2_63_1_error', 1)

# Test 3: Series with 10**400 (out-of-range)
try:
    result = pd.Series([10**400], dtype=object).convert_dtypes()
    probe('series_10_400_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_10_400_error', 1)

# Test 4: Series with mixed in-range and out-of-range
try:
    result = pd.Series([2**63, -1], dtype=object).convert_dtypes()
    probe('series_mixed_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_mixed_error', 1)

# Test 5: Series with out-of-range and pd.NA
try:
    result = pd.Series([2**64, pd.NA], dtype=object).convert_dtypes()
    probe('series_2_64_na_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_2_64_na_error', 1)

# Test 6: DataFrame with out-of-range column
try:
    result = pd.DataFrame({'a': [2**64, 1], 'b': [1, 2]}, dtype=object).convert_dtypes()
    probe('dataframe_dtype_a', str(result['a'].dtype))
    probe('dataframe_dtype_b', str(result['b'].dtype))
except OverflowError as e:
    probe('dataframe_error', 1)

# Test 7: Series with pyarrow backend and out-of-range int
try:
    result = pd.Series([2**64], dtype=object).convert_dtypes(dtype_backend='pyarrow')
    probe('series_2_64_pyarrow_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_2_64_pyarrow_error', 1)

# Test 8: Series with in-range value and pd.NA (should work)
try:
    result = pd.Series([2**62, pd.NA], dtype=object).convert_dtypes()
    probe('series_2_62_na_dtype', str(result.dtype))
    probe('series_2_62_na_success', 1)
except OverflowError as e:
    probe('series_2_62_na_error', 1)

fixed.buggy_overflow_tests:
import pandas as pd
import sys

# Test 1: Series with 2**64 (out-of-range) - should stay object
try:
    result = pd.Series([2**64], dtype=object).convert_dtypes()
    probe('series_2_64_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_2_64_error', 1)

# Test 2: Series with -(2**63)-1 (out-of-range) - should stay object
try:
    result = pd.Series([-(2**63)-1], dtype=object).convert_dtypes()
    probe('series_neg_2_63_1_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_neg_2_63_1_error', 1)

# Test 3: Series with 10**400 (out-of-range) - should stay object
try:
    result = pd.Series([10**400], dtype=object).convert_dtypes()
    probe('series_10_400_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_10_400_error', 1)

# Test 4: Series with mixed in-range and out-of-range - should stay object
try:
    result = pd.Series([2**63, -1], dtype=object).convert_dtypes()
    probe('series_mixed_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_mixed_error', 1)

# Test 5: Series with out-of-range and pd.NA - should stay object
try:
    result = pd.Series([2**64, pd.NA], dtype=object).convert_dtypes()
    probe('series_2_64_na_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_2_64_na_error', 1)

# Test 6: DataFrame with out-of-range column - column a should stay object, b should convert
try:
    result = pd.DataFrame({'a': [2**64, 1], 'b': [1, 2]}, dtype=object).convert_dtypes()
    probe('dataframe_dtype_a', str(result['a'].dtype))
    probe('dataframe_dtype_b', str(result['b'].dtype))
except OverflowError as e:
    probe('dataframe_error', 1)

# Test 7: Series with pyarrow backend and out-of-range int - should stay object
try:
    result = pd.Series([2**64], dtype=object).convert_dtypes(dtype_backend='pyarrow')
    probe('series_2_64_pyarrow_dtype', str(result.dtype))
except OverflowError as e:
    probe('series_2_64_pyarrow_error', 1)

# Test 8: Series with in-range value and pd.NA (should convert to UInt64)
try:
    result = pd.Series([2**62, pd.NA], dtype=object).convert_dtypes()
    probe('series_2_62_na_dtype', str(result.dtype))
    probe('series_2_62_na_success', 1)
except OverflowError as e:
    probe('series_2_62_na_error', 1)

# Test 9: Series with in-range uint64 and pd.NA (should convert to UInt64)
try:
    result = pd.Series([2**63, pd.NA], dtype=object).convert_dtypes()
    probe('series_2_63_na_dtype', str(result.dtype))
    probe('series_2_63_na_success', 1)
except OverflowError as e:
    probe('series_2_63_na_error', 1)
